-- Backend Engineering ("The Fracture") Act 21 -- "Advanced Event Systems" content.
-- Closes Arc IV (Stream). 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every prior Act. Uses the new slug-based id scheme
-- (world-be-advanced-events already exists; see 20260810320000 for its narrative row).

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be-advanced-events', 'world-be-advanced-events', 'advanced-event-systems', '21A - Advanced Event Systems', 'One optional field, added to the citizen-registration event, breaks four consumers nobody told -- three of them silently drop every event since, instead of erroring loudly. Arc IV closes here: schemas that evolve honestly, an event log worth trusting, and deduplication that does not quietly decide something never happened.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be-advanced-events-1', 'campaign-be-advanced-events', 'the-shape-of-an-event', 'The Shape of an Event', 'Schema evolution, schema registries, versioning, event sourcing, CQRS and materialized views -- what an event actually promises, and what changes to it are safe to make once someone else is already listening.', 1),
  ('operation-be-advanced-events-2', 'campaign-be-advanced-events', 'what-actually-happened', 'What Actually Happened', 'Stream processing, windowing, deduplication and the real meaning of exactly-once -- ending with the dedup job that quietly decided a real event never happened at all.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-advanced-events-01', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-1', 'event-schema-evolution', 'Event Schema Evolution', 'One optional field, added to the citizen-registration event, took down four consumers that were never told it was coming -- and three of them never even raised an error.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"schema-evolution-sim"}'::jsonb, '{"xp":230,"credits":45}'::jsonb, false, 1),
  ('mission-be-advanced-events-02', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-1', 'schema-registry-concepts', 'Schema Registry Concepts', 'A schema is a contract. A schema registry is what actually enforces it -- refusing to let an incompatible change reach a topic in the first place.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-advanced-events-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"schema-registry-sim"}'::jsonb, '{"xp":232,"credits":45}'::jsonb, false, 2),
  ('mission-be-advanced-events-03', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-1', 'event-versioning', 'Event Versioning', 'A registry stops bad changes from shipping. It does not help the consumer still running three versions behind, that never got told a v2 exists at all.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-advanced-events-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"event-versioning-sim"}'::jsonb, '{"xp":233,"credits":46}'::jsonb, false, 3),
  ('mission-be-advanced-events-04', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-1', 'event-sourcing', 'Event Sourcing', 'Every table Forge owns stores current state and throws the history away. Event sourcing keeps every event that ever happened, and treats current state as something computed, not stored.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-advanced-events-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"event-sourcing-sim"}'::jsonb, '{"xp":235,"credits":46}'::jsonb, false, 4),
  ('mission-be-advanced-events-05', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-1', 'cqrs', 'CQRS', 'A model built to validate writes correctly is a bad model for answering a fast, flexible read. CQRS splits the two jobs apart on purpose.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-advanced-events-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"cqrs-sim"}'::jsonb, '{"xp":236,"credits":46}'::jsonb, false, 5),
  ('mission-be-advanced-events-06', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-1', 'materialized-views', 'Materialized Views', 'The read side of CQRS has to come from somewhere. A materialized view is a disposable projection of the event log -- and disposable only holds if the projector rebuilding it is actually correct.', 'advanced', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be-advanced-events-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"materialized-views-sim"}'::jsonb, '{"xp":237,"credits":47}'::jsonb, false, 6),
  ('mission-be-advanced-events-07', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-2', 'stream-processing', 'Stream Processing', 'Waiting for a nightly batch job to sweep the event log stops being good enough the moment someone needs an answer in seconds, not hours.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-advanced-events-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"stream-processing-sim"}'::jsonb, '{"xp":238,"credits":47}'::jsonb, false, 7),
  ('mission-be-advanced-events-08', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-2', 'windowing-concepts', 'Windowing Concepts', 'A stream processor has to decide, live, when it is safe to call a running total final -- and every window size is a bet about how late an event is allowed to arrive.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-advanced-events-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"windowing-sim"}'::jsonb, '{"xp":239,"credits":47}'::jsonb, false, 8),
  ('mission-be-advanced-events-09', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-2', 'deduplication', 'Deduplication', 'Every stream produces duplicates: retried producers, redelivered messages, replayed offsets. Deciding what counts as the same event is the whole job -- and getting it wrong cuts both ways.', 'advanced', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be-advanced-events-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"deduplication-sim"}'::jsonb, '{"xp":241,"credits":48}'::jsonb, false, 9),
  ('mission-be-advanced-events-10', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-2', 'exactly-once-myth-vs-effect', 'Exactly-Once: Myth vs Effect', 'No broker delivers a message exactly once across a network that drops packets and retries. What is real is the effect of exactly-once -- and it comes from idempotent handling, not from trusting the broker.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-advanced-events-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"exactly-once-sim"}'::jsonb, '{"xp":242,"credits":48}'::jsonb, false, 10),
  ('mission-be-advanced-events-11', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-2', 'kafka-vs-rabbitmq-vs-bullmq', 'Kafka vs RabbitMQ vs BullMQ', 'Forge runs three different messaging tools for three different jobs, on purpose. Reaching for the wrong one means reaching for a guarantee it was never built to give.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-advanced-events-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"broker-comparison-sim"}'::jsonb, '{"xp":244,"credits":48}'::jsonb, false, 11),
  ('mission-be-advanced-events-12', 'world-be-advanced-events', 'campaign-be-advanced-events', 'operation-be-advanced-events-2', 'the-event-that-never-happened', 'The Event That Never Happened', 'A dedup job built on a guarantee that was never real quietly decided a citizen''s second, legitimate registration never happened. Diagnose the flawed assumption, pick the real fix, and see exactly where the pattern keeps landing.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-advanced-events-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"event-that-never-happened-boss-sim"}'::jsonb, '{"xp":541,"credits":126,"badgeIds":["event-that-never-happened"],"skillXp":{"messaging":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be-advanced-events-01', 1, 'mira', 'Arc IV''s last stretch starts with something almost embarrassing: one optional field, added to the citizen-registration event, took down four consumers that never even knew the change was coming.'),
  ('mission-be-advanced-events-01', 2, 'forge', 'Three of them didn''t error. They just... stopped processing. No exception, no alert, no log line that says "this broke." The event kept flowing. The consumers quietly stopped listening to what mattered in it.'),
  ('mission-be-advanced-events-01', 3, 'mira', 'A schema is a contract, and nobody renegotiates a contract by just changing it and hoping the other party notices. This Act is about making that contract explicit -- and honest about what it actually promises once an event goes out and can never be recalled.'),

  ('mission-be-advanced-events-02', 1, 'forge', 'A schema registry is the fix for "nobody told the consumers." Every producer registers the shape of an event before it''s allowed to publish it, and every consumer can check compatibility before it trusts a payload.'),
  ('mission-be-advanced-events-02', 2, 'forge', 'It doesn''t stop you from changing a schema. It stops you from changing it in a way that breaks whoever''s already listening, without anyone getting a say.'),

  ('mission-be-advanced-events-03', 1, 'mira', 'A registry catches incompatible changes before they ship. It doesn''t solve the harder problem: consumers still alive from three versions ago, that never got told a v2 exists at all.'),
  ('mission-be-advanced-events-03', 2, 'mira', 'Versioning is how an event tells its own age. Get it right and an old consumer can ignore what it doesn''t understand instead of silently misreading it.'),

  ('mission-be-advanced-events-04', 1, 'forge', 'Every table Forge owns stores the current state and throws the history away the moment something overwrites it. Event sourcing does the opposite: store every event that ever happened, and treat "current state" as something you compute, not something you store.'),
  ('mission-be-advanced-events-04', 2, 'forge', 'Lose the events and you''ve lost everything -- there''s no state to fall back on. Keep them, and you can answer "what did this record look like last Tuesday" by just replaying up to Tuesday.'),

  ('mission-be-advanced-events-05', 1, 'mira', 'Event sourcing gives you a perfect history and a genuinely bad way to answer "show me every citizen registered this month, sorted by district." Replaying the whole log for every read isn''t a database, it''s a performance incident waiting to happen.'),
  ('mission-be-advanced-events-05', 2, 'mira', 'CQRS splits the two jobs apart on purpose: one model that only accepts commands and appends events, and a completely separate model, built for reading, that''s allowed to be shaped however queries actually need it.'),

  ('mission-be-advanced-events-06', 1, 'forge', 'The read side of CQRS has to come from somewhere. A materialized view is a projection -- a table built by replaying events and updating itself every time a new one arrives, purpose-built for exactly the query it serves.'),
  ('mission-be-advanced-events-06', 2, 'forge', 'It''s a copy, not a source of truth. If a projector misses an event, or double-applies one, the view quietly disagrees with the log it was built from -- and nothing forces it back in line automatically.'),

  ('mission-be-advanced-events-07', 1, 'mira', 'Everything so far assumed someone eventually reads the log. Stream processing means computing something continuously, as events arrive, instead of waiting for a batch job to sweep through afterward.'),
  ('mission-be-advanced-events-07', 2, 'mira', 'The tradeoff is real: a batch job gets to see the whole dataset at once. A stream processor only ever sees what''s arrived so far, and has to decide, live, when it''s safe to call an answer final.'),

  ('mission-be-advanced-events-08', 1, 'forge', '"When is it safe to call an answer final" is exactly what windowing answers. A window is a slice of time a stream processor is willing to wait for and then commit to.'),
  ('mission-be-advanced-events-08', 2, 'forge', 'Pick a window too narrow and legitimate late events get treated as if they never happened. Pick it too wide and nothing''s ever final long enough to be useful.'),

  ('mission-be-advanced-events-09', 1, 'mira', 'This is where the Act starts pointing at Arc IV''s actual boss fight. Every stream gets duplicates -- retried producers, redelivered messages, replayed offsets. Deduplication is how a consumer decides two events are "the same one" and only acts on it once.'),
  ('mission-be-advanced-events-09', 2, 'forge', 'The whole thing lives or dies on one decision: what counts as the same event. Pick the wrong key and you''re not deduplicating retries anymore. You''re deduplicating two things that both actually happened.'),

  ('mission-be-advanced-events-10', 1, 'mira', 'Say it out loud once so it''s said: no messaging system delivers a message exactly once, physically, across a network that can drop packets and retry. That guarantee doesn''t exist at the transport level, full stop.'),
  ('mission-be-advanced-events-10', 2, 'forge', 'What''s achievable is the effect of exactly-once: a message can arrive twice, three times, however many times a retry demands, and the result of processing it still comes out identical to processing it once. That''s idempotency doing the actual work, not the broker.'),

  ('mission-be-advanced-events-11', 1, 'forge', 'Forge runs three different messaging tools for three different jobs, on purpose. Picking wrong doesn''t just cost performance -- it means reaching for delivery guarantees a tool was never built to give you.'),
  ('mission-be-advanced-events-11', 2, 'forge', 'Kafka: a durable, replayable log, built for many consumers reading the same history at their own pace. RabbitMQ: flexible routing and strong per-message delivery guarantees, built for task distribution. BullMQ: a Redis-backed job queue, built for a Node app that just needs reliable background jobs without running a separate broker.'),

  ('mission-be-advanced-events-12', 1, 'mira', 'Arc IV closes here. The event layer is versioned, the read side is honest about being a projection, and deduplication is supposed to mean a retried event only ever counts once. "Supposed to" is the word we''re here to test.'),
  ('mission-be-advanced-events-12', 2, 'forge', 'I pulled the dedup job''s assumptions apart. It was built on something we just spent a whole mission proving false: that "exactly-once" means an event physically arrives exactly once. It doesn''t. It never did.'),
  ('mission-be-advanced-events-12', 3, 'mira', 'So what happens when a job trusts a guarantee that was never real?'),
  ('mission-be-advanced-events-12', 4, 'forge', 'It drops something it shouldn''t. A citizen submitted a registration, it failed silently client-side, they resubmitted -- a completely legitimate second attempt. The dedup logic saw two events that looked alike and treated the second one as a duplicate. It was never delivered twice. It happened twice, for real, and the job only kept one of them.'),
  ('mission-be-advanced-events-12', 5, 'forge', 'I went looking for why that specific record, out of millions, got misjudged. The dedup key comes from hashing a field on the event. In a small percentage of records, that field carries the same doubled-slash tag I''ve been tracking since Act 2 -- and near enough every one of those records is exactly one the dedup logic gets wrong.'),
  ('mission-be-advanced-events-12', 6, 'mira', 'I''m not going to tell you that means something it might not. I don''t know what generates that tag, or why it correlates with exactly the records our own logic mishandles. I just know it does, here, again, and that''s the fourth time this Arc.'),
  ('mission-be-advanced-events-12', 7, 'mira', 'The event layer is versioned, replayable, and -- once we fix this -- honestly deduplicated. Every building block this Arc set out to build now exists. Whether any of it survives an attacker, a file too large for memory, or a real security review is Arc V''s problem. File this one. We''re bringing it with us.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be-advanced-events-01-o1', 'mission-be-advanced-events-01', 1, 'Diagnose the break', 'Find the evidence that explains why adding one optional field broke four consumers.'),
  ('mission-be-advanced-events-01-o2', 'mission-be-advanced-events-01', 2, 'Sort safe from breaking changes', 'Sort each kind of schema change into backward-compatible or breaking.'),

  ('mission-be-advanced-events-02-o1', 'mission-be-advanced-events-02', 1, 'Match the compatibility mode', 'Match each schema registry compatibility mode to what it actually guarantees.'),
  ('mission-be-advanced-events-02-o2', 'mission-be-advanced-events-02', 2, 'Confirm what the registry enforces', 'Decide what actually happens when a producer tries to publish an incompatible schema.'),

  ('mission-be-advanced-events-03-o1', 'mission-be-advanced-events-03', 1, 'Match the versioning strategy', 'Match each event versioning strategy to what it actually does.'),
  ('mission-be-advanced-events-03-o2', 'mission-be-advanced-events-03', 2, 'Find the version bug', 'Debug a consumer that assumes a field which isn''t guaranteed to exist.'),

  ('mission-be-advanced-events-04-o1', 'mission-be-advanced-events-04', 1, 'Order the replay', 'Order the steps event sourcing takes to compute an entity''s current state.'),
  ('mission-be-advanced-events-04-o2', 'mission-be-advanced-events-04', 2, 'Confirm the core idea', 'Decide what an event-sourced system actually stores as its source of truth.'),

  ('mission-be-advanced-events-05-o1', 'mission-be-advanced-events-05', 1, 'Sort command from query', 'Sort each responsibility into the command side or the query side.'),
  ('mission-be-advanced-events-05-o2', 'mission-be-advanced-events-05', 2, 'Diagnose the problem CQRS solves', 'Find the evidence that explains why splitting reads and writes is the actual fix.'),

  ('mission-be-advanced-events-06-o1', 'mission-be-advanced-events-06', 1, 'Find the projector bug', 'Debug a materialized view projector that double-counts after a replay.'),
  ('mission-be-advanced-events-06-o2', 'mission-be-advanced-events-06', 2, 'Confirm what a materialized view really is', 'Decide what a materialized view actually is, underneath the name.'),

  ('mission-be-advanced-events-07-o1', 'mission-be-advanced-events-07', 1, 'Match the stream processing concept', 'Match each concept to what it actually means.'),
  ('mission-be-advanced-events-07-o2', 'mission-be-advanced-events-07', 2, 'Diagnose batch vs stream', 'Find the evidence that actually justifies a stream processor over a bigger batch job.'),

  ('mission-be-advanced-events-08-o1', 'mission-be-advanced-events-08', 1, 'Match the window type', 'Match each windowing strategy to its definition.'),
  ('mission-be-advanced-events-08-o2', 'mission-be-advanced-events-08', 2, 'Diagnose the late-event problem', 'Find the root assumption behind a metric that keeps changing after it was already reported final.'),

  ('mission-be-advanced-events-09-o1', 'mission-be-advanced-events-09', 1, 'Diagnose the dedup key', 'Find the evidence that shows what actually makes a dedup key trustworthy.'),
  ('mission-be-advanced-events-09-o2', 'mission-be-advanced-events-09', 2, 'Find the dedup bug', 'Debug deduplication logic that merges two real events into one.'),

  ('mission-be-advanced-events-10-o1', 'mission-be-advanced-events-10', 1, 'Confirm the concept', 'Decide what''s actually wrong with trusting the broker alone for exactly-once.'),
  ('mission-be-advanced-events-10-o2', 'mission-be-advanced-events-10', 2, 'Diagnose the real guarantee', 'Find the evidence describing what exactly-once actually means in practice.'),

  ('mission-be-advanced-events-11-o1', 'mission-be-advanced-events-11', 1, 'Match the tool to the job', 'Match each messaging need to the tool actually built for it.'),
  ('mission-be-advanced-events-11-o2', 'mission-be-advanced-events-11', 2, 'Diagnose the mismatched choice', 'Find the evidence that explains why Kafka is the wrong tool here, not just an expensive one.'),

  ('mission-be-advanced-events-12-o1', 'mission-be-advanced-events-12', 1, 'Trace the dropped event', 'Find the evidence that shows the actual mechanism behind the dropped registration.'),
  ('mission-be-advanced-events-12-o2', 'mission-be-advanced-events-12', 2, 'Name the flawed assumption', 'Identify what the dedup job actually assumed that turned out to be false.'),
  ('mission-be-advanced-events-12-o3', 'mission-be-advanced-events-12', 3, 'Pick the real fix', 'Choose the fix that addresses the flawed assumption, not just a symptom of it.'),
  ('mission-be-advanced-events-12-o4', 'mission-be-advanced-events-12', 4, 'Correlate the pattern', 'Synthesize the diagnosis into what auditing the dedup key-generation logic turned up.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be-advanced-events-01-o1-c1', 'mission-be-advanced-events-01-o1', 1, 'investigation', 'Which evidence explains why adding one optional field could break four consumers that were never told about it?', '{"evidence":[{"id":"ev1","label":"Producer changelog","detail":"The citizen-registration event gained one new optional field, preferredContactMethod, with a sensible default when absent."},{"id":"ev2","label":"Consumer code","detail":"Three of the four consumers deserialize the event into a strict struct that rejects any payload containing a field it does not recognize."},{"id":"ev3","label":"Incident timeline","detail":"The schema change deployed at 14:02. The first consumer errors appeared at 14:03."}],"question":"Which evidence explains why adding one optional field could break four consumers that were never told about it?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be-advanced-events-01-o2-c1', 'mission-be-advanced-events-01-o2', 1, 'drag_and_drop', 'Sort each kind of schema change into backward-compatible or breaking.', '{"items":[{"id":"i1","text":"Adding a new optional field with a default value"},{"id":"i2","text":"Removing a field a consumer currently reads"},{"id":"i3","text":"Renaming an existing field"},{"id":"i4","text":"Adding a new required field with no default"},{"id":"i5","text":"Widening a numeric field''s type (e.g. int32 to int64)"}],"targets":[{"id":"t1","label":"Backward-compatible -- safe for existing consumers"},{"id":"t2","label":"Breaking -- unsafe for existing consumers"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t2","i4":"t2","i5":"t1"}}'::jsonb),

  ('mission-be-advanced-events-02-o1-c1', 'mission-be-advanced-events-02-o1', 1, 'drag_and_drop', 'Match each schema registry compatibility mode to what it actually guarantees.', '{"items":[{"id":"m1","text":"BACKWARD"},{"id":"m2","text":"FORWARD"},{"id":"m3","text":"FULL"},{"id":"m4","text":"NONE"}],"targets":[{"id":"t1","label":"A consumer on the new schema can still read events written under the old schema"},{"id":"t2","label":"A consumer still on the old schema can read events written under the new schema"},{"id":"t3","label":"Both directions hold at once"},{"id":"t4","label":"No compatibility checking at all -- any change is allowed through"}]}'::jsonb, '{"correctMapping":{"m1":"t1","m2":"t2","m3":"t3","m4":"t4"}}'::jsonb),
  ('mission-be-advanced-events-02-o2-c1', 'mission-be-advanced-events-02-o2', 1, 'multiple_choice', 'A producer tries to publish an event using a schema that would break existing consumers under the registry''s configured compatibility mode. What actually happens?', '{"question":"A producer tries to publish an event using a schema that would break existing consumers under the registry''s configured compatibility mode. What actually happens?","options":[{"id":"a","text":"The registry silently allows it and logs a warning"},{"id":"b","text":"The registry rejects the incompatible schema registration, so the breaking change never reaches a topic in the first place"},{"id":"c","text":"The registry automatically rewrites the event to match the old schema"},{"id":"d","text":"Nothing -- the registry only stores schemas, it never blocks anything"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-advanced-events-03-o1-c1', 'mission-be-advanced-events-03-o1', 1, 'drag_and_drop', 'Match each event versioning strategy to what it actually does.', '{"items":[{"id":"v1","text":"Envelope version field alongside the payload"},{"id":"v2","text":"Upcasting"},{"id":"v3","text":"Consumer-side version branching"}],"targets":[{"id":"t1","label":"Lets a consumer check which version an event is before deciding how to parse it"},{"id":"t2","label":"Transforms an old-version event into the shape of the newest version before handing it to business logic"},{"id":"t3","label":"Keeps separate handling code paths per version inside the same consumer -- works, but grows unmaintainable fast"}]}'::jsonb, '{"correctMapping":{"v1":"t1","v2":"t2","v3":"t3"}}'::jsonb),
  ('mission-be-advanced-events-03-o2-c1', 'mission-be-advanced-events-03-o2', 1, 'code_debugging', 'This handler crashes on every v1 event, which never had preferredContactMethod at all. Which line assumes a field that isn''t guaranteed to exist?', '{"language":"javascript","code":"function handleRegistration(event) {\n  const method = event.payload.preferredContactMethod.toUpperCase();\n  return createCitizen(event.payload, method);\n}","question":"This handler crashes on every v1 event, which never had preferredContactMethod at all. Which line assumes a field that isn''t guaranteed to exist?"}'::jsonb, '{"requiredLineIds":["  const method = event.payload.preferredContactMethod.toUpperCase();"]}'::jsonb),

  ('mission-be-advanced-events-04-o1-c1', 'mission-be-advanced-events-04-o1', 1, 'interactive_diagram', 'Order the steps event sourcing takes to compute an entity''s current state.', '{"diagramId":"event-sourcing-replay","hotspots":[{"id":"load_stream","label":"Load the event stream for this entity","explanation":"Every event ever recorded for this entity, in the order it happened."},{"id":"start_state","label":"Start from an empty initial state","explanation":"There is no stored current-state row to read -- state always starts from nothing."},{"id":"apply_events","label":"Apply each event in order, folding it into state","explanation":"Each event is a small, deterministic transformation of the state that came before it."},{"id":"return_state","label":"Return the resulting state as current","explanation":"What looks like a stored row anywhere else is really just the result of this replay, computed on demand."}],"task":"Order the steps event sourcing takes to compute an entity''s current state."}'::jsonb, '{"correctOrderIds":["load_stream","start_state","apply_events","return_state"]}'::jsonb),
  ('mission-be-advanced-events-04-o2-c1', 'mission-be-advanced-events-04-o2', 1, 'multiple_choice', 'What does an event-sourced system actually store as its source of truth?', '{"question":"What does an event-sourced system actually store as its source of truth?","options":[{"id":"a","text":"The current state of each entity, kept up to date by every write"},{"id":"b","text":"Every event that ever happened to an entity, with current state computed by replaying them"},{"id":"c","text":"A snapshot of state taken once per day"},{"id":"d","text":"Only the most recent event -- older ones are archived and unavailable"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-advanced-events-05-o1-c1', 'mission-be-advanced-events-05-o1', 1, 'drag_and_drop', 'Sort each responsibility into the command side or the query side.', '{"items":[{"id":"c1","text":"Validates a request and appends a new event if it is allowed"},{"id":"c2","text":"Answers a request like find every citizen registered this month, sorted by district"},{"id":"c3","text":"Optimized for consistent, correct writes -- not for flexible reading"},{"id":"c4","text":"Can be scaled and reshaped independently of how writes are validated"}],"targets":[{"id":"t1","label":"Command side (write model)"},{"id":"t2","label":"Query side (read model)"}]}'::jsonb, '{"correctMapping":{"c1":"t1","c2":"t2","c3":"t1","c4":"t2"}}'::jsonb),
  ('mission-be-advanced-events-05-o2-c1', 'mission-be-advanced-events-05-o2', 1, 'investigation', 'Which evidence explains why splitting reads and writes into separate models is the actual fix, not just a symptom of slow queries?', '{"evidence":[{"id":"ev1","label":"Incident note","detail":"Replaying the full event log on every dashboard query made the district-registration report take 40 seconds to load."},{"id":"ev2","label":"Team habit","detail":"The team was using the exact same model to validate writes and to serve every read-heavy report."},{"id":"ev3","label":"Load graph","detail":"Read traffic outnumbers write traffic roughly 200 to 1."}],"question":"Which evidence explains why splitting reads and writes into separate models is the actual fix, not just a symptom of slow queries?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-advanced-events-06-o1-c1', 'mission-be-advanced-events-06-o1', 1, 'code_debugging', 'After a consumer rebalance replays a few already-processed events, this district count view ends up too high. Which line is responsible?', '{"language":"javascript","code":"function onRegistrationEvent(event) {\n  districtCounts[event.district] += 1;\n  saveView(districtCounts);\n}","question":"After a consumer rebalance replays a few already-processed events, this district count view ends up too high. Which line is responsible?"}'::jsonb, '{"requiredLineIds":["  districtCounts[event.district] += 1;"]}'::jsonb),
  ('mission-be-advanced-events-06-o2-c1', 'mission-be-advanced-events-06-o2', 1, 'multiple_choice', 'What is a materialized view, most fundamentally?', '{"question":"What is a materialized view, most fundamentally?","options":[{"id":"a","text":"A cache with a TTL"},{"id":"b","text":"A disposable, rebuildable projection of the event log, shaped for a specific query -- not a second source of truth"},{"id":"c","text":"A backup copy of the primary database"},{"id":"d","text":"A schema migration tool"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-advanced-events-07-o1-c1', 'mission-be-advanced-events-07-o1', 1, 'drag_and_drop', 'Match each concept to what it actually means.', '{"items":[{"id":"s1","text":"Stateless transformation (e.g. filter, map)"},{"id":"s2","text":"Stateful aggregation (e.g. a running count per district)"},{"id":"s3","text":"Continuous processing"},{"id":"s4","text":"Batch processing"}],"targets":[{"id":"t1","label":"Processes each event independently, no memory of prior events needed"},{"id":"t2","label":"Needs to remember something across events to produce a correct answer"},{"id":"t3","label":"Computes results as events arrive, without waiting for a defined end"},{"id":"t4","label":"Computes results over a complete, bounded dataset collected beforehand"}]}'::jsonb, '{"correctMapping":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb),
  ('mission-be-advanced-events-07-o2-c1', 'mission-be-advanced-events-07-o2', 1, 'investigation', 'Which evidence is the actual reason a stream processor, not a bigger nightly batch job, is the right fix here?', '{"evidence":[{"id":"ev1","label":"Dashboard requirement","detail":"Ops wants district registration counts to update within seconds of a citizen registering, not once a day."},{"id":"ev2","label":"Current setup","detail":"A nightly batch job recomputes every count from scratch by scanning the full event log."},{"id":"ev3","label":"Volume note","detail":"The event log has grown to 40 million events and is still growing."}],"question":"Which evidence is the actual reason a stream processor, not a bigger nightly batch job, is the right fix here?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be-advanced-events-08-o1-c1', 'mission-be-advanced-events-08-o1', 1, 'drag_and_drop', 'Match each windowing strategy to its definition.', '{"items":[{"id":"w1","text":"Tumbling window"},{"id":"w2","text":"Sliding window"},{"id":"w3","text":"Session window"}],"targets":[{"id":"t1","label":"Fixed-size, non-overlapping -- every event belongs to exactly one window"},{"id":"t2","label":"Fixed-size but overlapping -- an event can belong to more than one window"},{"id":"t3","label":"Sized by a gap of inactivity, not a fixed duration -- ends when events stop arriving for a while"}]}'::jsonb, '{"correctMapping":{"w1":"t1","w2":"t2","w3":"t3"}}'::jsonb),
  ('mission-be-advanced-events-08-o2-c1', 'mission-be-advanced-events-08-o2', 1, 'investigation', 'Which evidence is the root assumption the windowing design got wrong, not just a symptom of it?', '{"evidence":[{"id":"ev1","label":"Metric drift","detail":"An hourly registration count for 09:00-10:00, already reported as final, changes an hour later when a delayed event finally arrives."},{"id":"ev2","label":"Network note","detail":"A subset of edge devices buffer events locally and can arrive minutes to hours late."},{"id":"ev3","label":"Team assumption","detail":"The stream job assumed every event arrives in order, close to when it actually happened."}],"question":"Which evidence is the root assumption the windowing design got wrong, not just a symptom of it?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be-advanced-events-09-o1-c1', 'mission-be-advanced-events-09-o1', 1, 'investigation', 'Which evidence shows what actually makes a dedup key trustworthy, versus what merely makes it convenient to compute?', '{"evidence":[{"id":"ev1","label":"Dedup implementation note","detail":"Two events are treated as duplicates if their message key and a hash of the payload match."},{"id":"ev2","label":"Incident","detail":"Two citizens submitting identical-looking forms -- same district, same permit type, same day -- got merged into one record."},{"id":"ev3","label":"Broker doc","detail":"The broker guarantees a message will not be delivered before it is durably written -- it says nothing about whether the same logical event can be produced twice by an upstream retry."}],"question":"Which evidence shows what actually makes a dedup key trustworthy, versus what merely makes it convenient to compute?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),
  ('mission-be-advanced-events-09-o2-c1', 'mission-be-advanced-events-09-o2', 1, 'code_debugging', 'Two citizens who happened to submit identical form answers on the same day get treated as one event. Which line is responsible?', '{"language":"javascript","code":"function isDuplicate(event, seen) {\n  const key = hash(event.payload);\n  if (seen.has(key)) return true;\n  seen.add(key);\n  return false;\n}","question":"Two citizens who happened to submit identical form answers on the same day get treated as one event. Which line is responsible?"}'::jsonb, '{"requiredLineIds":["  const key = hash(event.payload);"]}'::jsonb),

  ('mission-be-advanced-events-10-o1-c1', 'mission-be-advanced-events-10-o1', 1, 'multiple_choice', 'A teammate claims the broker''s exactly-once guarantees alone mean idempotent handlers aren''t necessary. What is actually wrong with that claim?', '{"question":"A teammate claims the broker''s exactly-once guarantees alone mean idempotent handlers aren''t necessary. What is actually wrong with that claim?","options":[{"id":"a","text":"Nothing -- broker-level exactly-once semantics guarantee no consumer ever sees a duplicate, full stop"},{"id":"b","text":"Broker-level exactly-once semantics apply to producer-to-broker writes and specific consume-transform-produce pipelines -- they do not make arbitrary side effects, like a database write or a dispatch call, idempotent on their own"},{"id":"c","text":"Exactly-once is only available in RabbitMQ, not Kafka"},{"id":"d","text":"Idempotent handlers are only needed for financial transactions"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-advanced-events-10-o2-c1', 'mission-be-advanced-events-10-o2', 1, 'investigation', 'Which evidence describes what exactly-once actually means in practice, underneath the marketing language?', '{"evidence":[{"id":"ev1","label":"Vendor doc","detail":"The broker''s marketing material advertises exactly-once delivery."},{"id":"ev2","label":"Engineering note","detail":"What is actually implemented is at-least-once delivery plus deduplication on the consumer side, which produces the same practical effect as exactly-once processing."},{"id":"ev3","label":"Incident","detail":"A consumer crashed after processing an event but before committing its offset, and reprocessed the same event on restart."}],"question":"Which evidence describes what exactly-once actually means in practice, underneath the marketing language?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-advanced-events-11-o1-c1', 'mission-be-advanced-events-11-o1', 1, 'drag_and_drop', 'Match each messaging need to the tool actually built for it.', '{"items":[{"id":"k1","text":"Every consumer needs to replay the full history of events from the beginning, independently, at its own pace"},{"id":"k2","text":"Need flexible routing and strong per-message acknowledgment for distributing tasks to workers"},{"id":"k3","text":"A single Node.js app needs a reliable background job queue without standing up a separate broker"}],"targets":[{"id":"t1","label":"Kafka"},{"id":"t2","label":"RabbitMQ"},{"id":"t3","label":"BullMQ"}]}'::jsonb, '{"correctMapping":{"k1":"t1","k2":"t2","k3":"t3"}}'::jsonb),
  ('mission-be-advanced-events-11-o2-c1', 'mission-be-advanced-events-11-o2', 1, 'investigation', 'Which evidence best explains why Kafka is the wrong tool here, not just an expensive one?', '{"evidence":[{"id":"ev1","label":"Architecture note","detail":"The team runs a full multi-broker Kafka cluster just to schedule three background email jobs a minute."},{"id":"ev2","label":"Ops complaint","detail":"Nobody on the team has ever needed to replay history or support more than one consumer group for these jobs."},{"id":"ev3","label":"Alternative","detail":"A Redis instance the team already runs sits mostly idle."}],"question":"Which evidence best explains why Kafka is the wrong tool here, not just an expensive one?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-advanced-events-12-o1-c1', 'mission-be-advanced-events-12-o1', 1, 'investigation', 'Which evidence shows the actual mechanism behind the dropped registration, not just the fact that it happened?', '{"evidence":[{"id":"ev1","label":"Client report","detail":"A citizen submitted the registration form, got a client-side timeout, and resubmitted. Both submissions reached the server."},{"id":"ev2","label":"Dedup job log","detail":"Event evt-88213 hashed to the same dedup key as evt-88190, submitted four minutes earlier by the same citizen; the job discarded evt-88213 as a duplicate."},{"id":"ev3","label":"Dedup key spec","detail":"Dedup key = hash(citizenId + formFieldChecksum). Both submissions had identical form data, because the citizen re-entered exactly the same answers the second time."}],"question":"Which evidence shows the actual mechanism behind the dropped registration, not just the fact that it happened?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),
  ('mission-be-advanced-events-12-o2-c1', 'mission-be-advanced-events-12-o2', 1, 'multiple_choice', 'What did the dedup job actually assume that turned out to be false?', '{"question":"What did the dedup job actually assume that turned out to be false?","options":[{"id":"a","text":"That the broker guarantees each event is physically delivered exactly once, so two events with identical content must be the same physical delivery repeated"},{"id":"b","text":"That every citizen submits a registration form only once in their life"},{"id":"c","text":"That the dedup window was too short to catch the second submission"},{"id":"d","text":"That hashing more fields would have prevented the collision"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-advanced-events-12-o3-c1', 'mission-be-advanced-events-12-o3', 1, 'multiple_choice', 'Which fix actually addresses the flawed assumption, rather than working around a symptom of it?', '{"question":"Which fix actually addresses the flawed assumption, rather than working around a symptom of it?","options":[{"id":"a","text":"Turn on the broker''s built-in exactly-once-semantics transactional producer mode and remove the application-level dedup logic entirely"},{"id":"b","text":"Widen the dedup window so more retries get caught before they are treated as new events"},{"id":"c","text":"Generate the dedup key from something that actually identifies a distinct submission attempt -- a client-generated idempotency key issued once per real submission intent -- and keep the handler idempotent so a genuine retry produces the same effect no matter how many times it is processed"},{"id":"d","text":"Have consumers retry less aggressively so fewer duplicate-looking events are produced"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be-advanced-events-12-o4-c1', 'mission-be-advanced-events-12-o4', 1, 'boss_encounter', 'Having traced the drop, named the flawed assumption and picked the real fix, state what auditing the dedup key-generation logic turned up.', '{"stages":[{"objectiveRef":"mission-be-advanced-events-12-o1","label":"Trace the dropped event"},{"objectiveRef":"mission-be-advanced-events-12-o2","label":"Name the flawed assumption"},{"objectiveRef":"mission-be-advanced-events-12-o3","label":"Pick the real fix"}],"task":"Having traced the drop, named the flawed assumption and picked the real fix, state what auditing the dedup key-generation logic turned up: in a small percentage of records, the field it hashes on carries the same doubled-slash tag Forge has tracked since Act 2 -- and those are exactly the records the dedup logic gets wrong. Nobody knows why yet. That correlation is what closes Arc IV."}'::jsonb, '{"requiredObjectiveIds":["mission-be-advanced-events-12-o1","mission-be-advanced-events-12-o2","mission-be-advanced-events-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be-advanced-events-01-o1-c1', 'orientation', 'One of these three entries describes a design decision. The other two are things that decision produced.', 10, 1),
  ('mission-be-advanced-events-01-o1-c1', 'concept', 'A field being optional on the producer side means nothing if the consumer''s deserializer treats any unrecognized field as an error.', 20, 2),
  ('mission-be-advanced-events-01-o1-c1', 'solution', 'ev2: the strict, closed deserializer is the actual root cause -- it rejects any field it doesn''t already know about, which is exactly what turns a safe addition into a breaking one.', 30, 3),
  ('mission-be-advanced-events-01-o2-c1', 'orientation', 'Ask, for each change, whether an old consumer that never saw the change could still parse a new event without crashing.', 10, 1),
  ('mission-be-advanced-events-01-o2-c1', 'solution', 'Safe: adding an optional field with a default, widening a numeric type. Breaking: removing a field, renaming a field, adding a required field with no default.', 20, 2),

  ('mission-be-advanced-events-02-o1-c1', 'orientation', 'Two of these look in one direction. One looks in the other. One turns compatibility checking off entirely.', 10, 1),
  ('mission-be-advanced-events-02-o1-c1', 'solution', 'BACKWARD -- new schema reads old data. FORWARD -- old schema reads new data. FULL -- both. NONE -- no checking at all.', 20, 2),
  ('mission-be-advanced-events-02-o2-c1', 'orientation', 'A registry exists specifically to be a gate, not a log.', 10, 1),
  ('mission-be-advanced-events-02-o2-c1', 'solution', 'The registry rejects the incompatible schema registration outright -- the breaking change never even makes it onto a topic.', 20, 2),

  ('mission-be-advanced-events-03-o1-c1', 'orientation', 'One of these lives in every event. One runs once, at read time, to normalize old shapes. One lives permanently inside consumer code.', 10, 1),
  ('mission-be-advanced-events-03-o1-c1', 'solution', 'Envelope version field -- lets a consumer check the version. Upcasting -- transforms old events into the newest shape. Version branching -- separate code paths per version inside the consumer.', 20, 2),
  ('mission-be-advanced-events-03-o2-c1', 'orientation', 'The handler never checks which version of the event it received before reading a field that only exists on the newer one.', 10, 1),
  ('mission-be-advanced-events-03-o2-c1', 'concept', 'A field introduced in v2 is undefined on every v1 event -- calling a method on undefined throws immediately.', 20, 2),
  ('mission-be-advanced-events-03-o2-c1', 'solution', 'const method = event.payload.preferredContactMethod.toUpperCase(); assumes the field exists on every event, but it only exists from v2 onward.', 30, 3),

  ('mission-be-advanced-events-04-o1-c1', 'orientation', 'Nothing can be folded into state before there is a starting state and a stream to fold.', 10, 1),
  ('mission-be-advanced-events-04-o1-c1', 'solution', 'Load the event stream, start from an empty initial state, apply each event in order, then return the result as current state.', 20, 2),
  ('mission-be-advanced-events-04-o2-c1', 'orientation', 'A snapshot is an optimization on top of the real source of truth, not the source of truth itself.', 10, 1),
  ('mission-be-advanced-events-04-o2-c1', 'solution', 'Every event that ever happened, with current state computed on demand by replaying them -- not a stored current-state row.', 20, 2),

  ('mission-be-advanced-events-05-o1-c1', 'orientation', 'The command side changes data. The query side only ever answers questions about it.', 10, 1),
  ('mission-be-advanced-events-05-o1-c1', 'solution', 'Command side: validates and appends events, optimized for correctness. Query side: answers reads, can be scaled and reshaped independently.', 20, 2),
  ('mission-be-advanced-events-05-o2-c1', 'orientation', 'Two of these describe the symptom. One describes the design choice that caused it.', 10, 1),
  ('mission-be-advanced-events-05-o2-c1', 'concept', 'A model built to guarantee correct writes and a model built to answer fast, flexible reads are pulling in opposite directions -- using one model for both means neither job gets done well.', 20, 2),
  ('mission-be-advanced-events-05-o2-c1', 'solution', 'ev2: the same model handling both writes and heavy reads is the root cause -- the slow query and the read/write ratio are just where that choice shows up.', 30, 3),

  ('mission-be-advanced-events-06-o1-c1', 'orientation', 'A replayed event should never change the view by more than it already changed it the first time.', 10, 1),
  ('mission-be-advanced-events-06-o1-c1', 'concept', 'An unconditional increment has no memory of which event ids it has already applied -- replaying the same event just adds to the count again.', 20, 2),
  ('mission-be-advanced-events-06-o1-c1', 'solution', 'districtCounts[event.district] += 1; applies unconditionally on every call, with no check for whether this event was already counted -- that is what makes a replay double-count.', 30, 3),
  ('mission-be-advanced-events-06-o2-c1', 'orientation', 'Ask what happens if you deleted the view right now.', 10, 1),
  ('mission-be-advanced-events-06-o2-c1', 'solution', 'It is a disposable, rebuildable projection shaped for one query -- not a second source of truth, and not a backup.', 20, 2),

  ('mission-be-advanced-events-07-o1-c1', 'orientation', 'Two of these describe how much memory a computation needs. Two describe when the computation runs.', 10, 1),
  ('mission-be-advanced-events-07-o1-c1', 'solution', 'Stateless -- no memory needed. Stateful -- needs to remember something. Continuous -- runs as events arrive. Batch -- runs over a complete dataset collected first.', 20, 2),
  ('mission-be-advanced-events-07-o2-c1', 'orientation', 'The volume and the current setup describe the problem''s shape. One entry describes the actual requirement driving the fix.', 10, 1),
  ('mission-be-advanced-events-07-o2-c1', 'solution', 'ev1: needing an update within seconds, not once a day, is the actual requirement that rules out a nightly batch job -- volume alone would only argue for a faster batch job.', 20, 2),

  ('mission-be-advanced-events-08-o1-c1', 'orientation', 'One window type never overlaps. One always can. One isn''t sized by time at all.', 10, 1),
  ('mission-be-advanced-events-08-o1-c1', 'solution', 'Tumbling -- fixed, non-overlapping. Sliding -- fixed, overlapping. Session -- sized by a gap of inactivity.', 20, 2),
  ('mission-be-advanced-events-08-o2-c1', 'orientation', 'The metric drift and the network note are both consequences. One entry is the design assumption that made them possible.', 10, 1),
  ('mission-be-advanced-events-08-o2-c1', 'concept', 'A window that assumes events arrive in order, close to when they happened, has no plan for a legitimately late one -- it just calls the window final and moves on.', 20, 2),
  ('mission-be-advanced-events-08-o2-c1', 'solution', 'ev3: the assumption that every event arrives in order, close to real time, is the root cause -- the drifting metric and the late-arriving devices are just where that assumption breaks.', 30, 3),

  ('mission-be-advanced-events-09-o1-c1', 'orientation', 'The incident and the broker doc both describe effects. One entry describes the actual rule the dedup key follows.', 10, 1),
  ('mission-be-advanced-events-09-o1-c1', 'concept', 'A key built purely from message key plus a content hash treats any two events with identical content as the same event -- even when they are two separate, legitimate things that happened to look alike.', 20, 2),
  ('mission-be-advanced-events-09-o1-c1', 'solution', 'ev1: the implementation note is the actual mechanism -- a dedup key based on content match, not true identity, is what makes it untrustworthy the moment two real events look alike.', 30, 3),
  ('mission-be-advanced-events-09-o2-c1', 'orientation', 'The bug is in how the key is generated, not in the has-it-been-seen check itself.', 10, 1),
  ('mission-be-advanced-events-09-o2-c1', 'solution', 'const key = hash(event.payload); hashes only the content, so two distinct events with identical content collide onto the same key and get merged.', 20, 2),

  ('mission-be-advanced-events-10-o1-c1', 'orientation', 'A guarantee about how the broker writes a message is not the same as a guarantee about what your code does with it afterward.', 10, 1),
  ('mission-be-advanced-events-10-o1-c1', 'solution', 'Broker-level exactly-once semantics cover producer-to-broker writes and specific pipelines -- they do not automatically make an arbitrary side effect, like a database write, safe to run twice.', 20, 2),
  ('mission-be-advanced-events-10-o2-c1', 'orientation', 'The vendor doc is marketing language. The incident is one instance of a duplicate. One entry describes the actual mechanism underneath both.', 10, 1),
  ('mission-be-advanced-events-10-o2-c1', 'solution', 'ev2: at-least-once delivery plus consumer-side deduplication is what actually produces the exactly-once effect -- the marketing term describes the outcome, not the mechanism.', 20, 2),

  ('mission-be-advanced-events-11-o1-c1', 'orientation', 'One tool is a replayable log. One is a routing and task-distribution broker. One is a lightweight queue riding on a data store you probably already run.', 10, 1),
  ('mission-be-advanced-events-11-o1-c1', 'solution', 'Replayable history for many independent consumers -> Kafka. Flexible routing and per-message guarantees for task distribution -> RabbitMQ. Simple background jobs without a separate broker -> BullMQ.', 20, 2),
  ('mission-be-advanced-events-11-o2-c1', 'orientation', 'The architecture note describes the cost. The ops complaint describes what was never actually needed.', 10, 1),
  ('mission-be-advanced-events-11-o2-c1', 'solution', 'ev2: nobody ever needed replay or multiple consumer groups -- that is what makes Kafka the wrong tool, not just an expensive one.', 20, 2),

  ('mission-be-advanced-events-12-o1-c1', 'orientation', 'The client report and the job log both describe what happened. One entry describes why the key generation actually collided.', 10, 1),
  ('mission-be-advanced-events-12-o1-c1', 'concept', 'A key built from identical form content will always collide for two submissions with identical answers -- whether or not they are actually the same physical delivery.', 20, 2),
  ('mission-be-advanced-events-12-o1-c1', 'solution', 'ev3: the key spec is the actual mechanism -- identical form data produces an identical hash regardless of whether the two events are the same delivery or two real, separate submissions.', 30, 3),
  ('mission-be-advanced-events-12-o2-c1', 'orientation', 'This is the exact myth Mission 10 spent its whole runtime naming.', 10, 1),
  ('mission-be-advanced-events-12-o2-c1', 'solution', 'a: the job assumed physical exactly-once delivery is real, and used content-match alone as proof of that -- a guarantee that never existed at the transport level.', 20, 2),
  ('mission-be-advanced-events-12-o3-c1', 'orientation', 'Two of these options treat the delivery layer as the problem. Only one actually changes what counts as the same event.', 10, 1),
  ('mission-be-advanced-events-12-o3-c1', 'concept', 'Broker-side exactly-once-semantics settings do not know anything about form submissions -- the fix has to live in how the dedup key is generated and in making the handler itself idempotent.', 20, 2),
  ('mission-be-advanced-events-12-o3-c1', 'solution', 'c: a real, submission-scoped idempotency key plus an idempotent handler fixes the actual assumption -- the other options adjust delivery-layer knobs that were never the real problem.', 30, 3),
  ('mission-be-advanced-events-12-o4-c1', 'orientation', 'Look at what the dedup key''s own input field had in common across the records it got wrong.', 15, 1),
  ('mission-be-advanced-events-12-o4-c1', 'solution', 'A small percentage of records carry the same doubled-slash tag Forge has tracked since Act 2 in the exact field the dedup key hashes on -- and those are exactly the records the logic mishandles. Nobody yet knows why. It is the fourth time this Arc the pattern has surfaced somewhere that touches real data correctness.', 25, 2);
